<?php
if(!defined('ABSPATH'))exit;
function pa_admin_badge($status){$labels=pa_statuses()+['signed'=>'Signed','unsigned'=>'Signature pending','clean'=>'Ready to download','quarantined'=>'Analysis pending','infected'=>'Blocked'];return '<span class="pa-badge pa-badge-'.esc_attr($status).'">'.esc_html($labels[$status]??ucwords(str_replace('_',' ',$status))).'</span>';}
function pa_document_url($id,$revision,$doc){return wp_nonce_url(admin_url('admin-post.php?action=pa_download&record='.$id.'&format=pdf&revision='.$revision.'&document='.$doc),'pa_download_'.$id);}
function pa_admin_documents($id,$p,$revision){
 if($revision){$submitted=pa_get($id,'_pa_revision_'.$revision);if($submitted)$p=$submitted;}
 $names=['customer'=>'Customer application','credit'=>'Credit application','terms'=>'Transport terms','claim'=>'Freight claim'];
 echo '<section class="pa-document-workspace"><div class="pa-section-title"><div><span class="pa-kicker">DOCUMENT WORKSPACE</span><h2>Review one document at a time</h2></div><span>'.($revision?'Latest submitted revision '.(int)$revision:'Draft · not submitted').'</span></div><p>Original-layout exports include the completed paper form and a digital supplement with full values and signature records. '.($revision?'These details and exports use the same submitted revision. Any newer, unsubmitted corrections are not included.':'Draft exports are marked NOT SUBMITTED.').'</p><nav class="pa-doc-navigation" aria-label="Request documents">';
 foreach(pa_document_keys($p) as $doc)echo '<a href="#pa-doc-'.esc_attr($doc).'">'.esc_html($names[$doc]).' <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24"><path d="M6 6l12 12M6 18h12V6" fill="none" stroke="currentColor" stroke-width="1.6"/></svg></a>';echo '</nav>';
 foreach(pa_document_keys($p) as $i=>$doc){$needed=array_filter(pa_signatures_needed($p),fn($spec)=>$spec['doc']===$doc);$signed=0;foreach($needed as $slot=>$spec)if(!empty($p['signatures'][$slot]))$signed++;
 echo '<details class="pa-document-card" id="pa-doc-'.esc_attr($doc).'"'.($i===0?' open':'').'><summary><span><span class="pa-kicker">DOCUMENT '.sprintf('%02d',$i+1).'</span><strong>'.esc_html($names[$doc]).'</strong></span>'.pa_admin_badge($signed===count($needed)?'signed':'unsigned').'</summary><div class="pa-document-body"><div class="pa-document-actions"><p>'.(int)$signed.' / '.count($needed).' signatures saved</p><a class="button button-primary" href="'.esc_url(pa_document_url($id,$revision,$doc)).'">Export '.esc_html($doc).' PDF'.(!$revision?' · DRAFT':'').'</a></div>';
 $group='';foreach(pa_document_fields($p,$doc) as $f){if(($f['condition']??'')==='credit'&&($p['data']['request_credit']??'')!=='Yes')continue;if($group!==$f['group']){if($group)echo '</dl>';echo '<h3>'.esc_html(ucwords(str_replace('_',' ',$f['group']))).'</h3><dl class="pa-document-fields">';$group=$f['group'];}$v=$p['data'][$f['key']]??'';echo '<dt>'.esc_html($f['label']).'</dt><dd>';if($v==='')echo '<span class="pa-muted">Not provided</span>';elseif(in_array($f['key'],['tax_id','bank_account'],true))echo '<details><summary>•••• '.esc_html(substr($v,-4)).' · Show value</summary>'.esc_html($v).'</details>';else echo esc_html($f['type']==='checkbox'?'Confirmed':$v);echo '</dd>';}
 if($group)echo '</dl>';echo '<div class="pa-document-signatures">';foreach($needed as $slot=>$spec){$s=$p['signatures'][$slot]??null;echo '<figure><figcaption><strong>'.esc_html($spec['label']).'</strong><span>'.esc_html($s?$s['name'].' · '.$s['signed_at']:'Awaiting signature').'</span></figcaption>';if($s)echo '<img class="pa-sign-preview" alt="Saved signature" src="'.esc_attr('data:'.$s['image']['mime'].';base64,'.$s['image']['base64']).'">';echo '</figure>';}echo '</div></div></details>';
 }
 if($p['kind']==='application'&&($p['data']['request_credit']??'')!=='Yes')echo '<p class="pa-muted">Credit application: not requested by this customer.</p>';
 echo '</section>';
}
function pa_admin_evidence($id,$p){if(empty($p['files']))return;
 echo '<section class="pa-admin-panel pa-evidence"><span class="pa-kicker">ATTACHMENTS</span><h2>Supporting evidence</h2><p>Uploading saves the file. Only an approved security scan enables its download. Pending does not necessarily mean an infection.</p><div class="pa-evidence-grid">';
 foreach($p['files'] as $slot=>$file){$clean=pa_attachment_clean($file);$status=$clean?'clean':(($file['scan']['status']??'')==='infected'?'infected':'quarantined');echo '<article><h3>'.esc_html(ucfirst($slot)).'</h3><p>'.esc_html($file['name']).'</p><p class="pa-muted">'.esc_html(size_format($file['size'])).'</p>'.pa_admin_badge($status);if($clean)echo '<p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=pa_download&record='.$id.'&format=file&slot='.$slot),'pa_download_'.$id)).'">Download '.esc_html($slot).'</a></p>';else echo '<p class="pa-muted">Download locked until approval.</p>';echo '</article>';}
 echo '</div>';if(current_user_can('manage_options')){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pa_scan"><input type="hidden" name="record" value="'.$id.'">';wp_nonce_field('pa_scan_'.$id);echo '<button class="button">Run configured attachment scanner</button></form>';}echo '</section>';
}
